import numpy as np
DESCRIPTION="Tokens are one-hot plus a 5x6 position table U; two single-head attentions in a canonical basis (QK folded to B,C; OV folded to V,W); readout K at position 4."
D=""
a=np.array([int(D[i:i+3],36)for i in range(0,612,3)])-2e4
b=a.reshape(34,6)/1e3
U=b[:5];B=b[5:11];V=b[11:17];C=b[17:23];W=b[23:29];K=b[29:].T
def at(S,E,V):
    p=E@S@E.transpose(0,2,1);p=np.exp(p-p.max(-1,keepdims=True));p/=p.sum(-1,keepdims=True)
    return p,p@(E@V)
def model(x,iv):
    n,P=x.shape
    h=lambda nm,v,k:iv(nm,v.reshape(n,-1)).reshape(n,P,k)
    E=h('em',np.eye(6)[x]+U,6)
    p,a=at(B,E,V)
    r=h('r0',h('a0',a,6)+E,6)
    p,a=at(C,r,W)
    return h('r1',r+a,6)[:,4]@K
ALIGN={'em':['embed'],'a0':['attn0.out'],'r0':['resid0.mid'],'r1':['resid1.mid']}
